    #[error("release state does not contain operation `{id:?}`")]
    UnknownOperation { id: Box<ReleaseOperationId> },
    #[error("operation `{id:?}` cannot transition from {from:?}")]
    InvalidTransition {
        id: Box<ReleaseOperationId>,
        from: OperationState,
    },
}

/// A terminal receipt derived only from a complete execution state.
#[derive(Clone, Debug, PartialEq, Eq, JsonSchema)]
#[schemars(with = "ReleaseReceiptV1Wire")]
pub struct ReleaseReceiptV1 {
    schema_version: u8,
    intent_digest: IntentDigest,
    outcomes: BTreeMap<ReleaseOperationId, OperationOutcome>,
}

#[derive(Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct ReleaseReceiptV1Wire {
    schema_version: u8,
    intent_digest: IntentDigest,
    outcomes: Vec<OperationOutcomeEntryV1>,
}

#[derive(Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct OperationOutcomeEntryV1 {
    operation: ReleaseOperationId,
    outcome: OperationOutcome,
}

impl Serialize for ReleaseReceiptV1 {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        ReleaseReceiptV1Wire {
            schema_version: self.schema_version,
            intent_digest: self.intent_digest.clone(),
            outcomes: self
                .outcomes
                .iter()
                .map(|(operation, outcome)| OperationOutcomeEntryV1 {
                    operation: operation.clone(),
                    outcome: *outcome,
                })
                .collect(),
        }
        .serialize(serializer)
    }
}

impl<'de> Deserialize<'de> for ReleaseReceiptV1 {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let wire = ReleaseReceiptV1Wire::deserialize(deserializer)?;
        Self::from_wire(wire).map_err(serde::de::Error::custom)
    }
}

impl ReleaseReceiptV1 {
    pub const SCHEMA_VERSION: u8 = 1;

    /// Constructs a receipt only when state is complete and exact for `intent`.
    pub fn from_state(intent: &ReleaseIntentV1, state: &ReleaseExecutionStateV1) -> Result<Self, ReleaseReceiptError> {
        state
            .validate_for_intent(intent)
            .map_err(ReleaseReceiptError::InvalidState)?;
        let mut outcomes = BTreeMap::new();
        for (id, operation_state) in &state.operations {
            let outcome = match operation_state {
                OperationState::Published => OperationOutcome::Published,
                OperationState::AlreadySatisfied => OperationOutcome::AlreadySatisfied,
                OperationState::Failed => OperationOutcome::Failed,
                OperationState::Blocked { reason } => OperationOutcome::Blocked { reason: *reason },
                OperationState::Pending | OperationState::Attempting => {
                    return Err(ReleaseReceiptError::NonTerminalOperation {
                        id: Box::new(id.clone()),
                    });
                }
            };
            outcomes.insert(id.clone(), outcome);
        }
        Ok(Self {
            schema_version: Self::SCHEMA_VERSION,
            intent_digest: state.intent_digest.clone(),
            outcomes,
        })
    }

    pub fn intent_digest(&self) -> &IntentDigest {
        &self.intent_digest
    }

    /// Validates exact intent and operation-roster binding before reconciliation.
    pub fn validate_for_intent(&self, intent: &ReleaseIntentV1) -> Result<(), ReleaseReceiptError> {
        if self.schema_version != Self::SCHEMA_VERSION {
            return Err(ReleaseReceiptError::UnsupportedSchema {
                found: self.schema_version,
            });
        }
        if self.intent_digest != intent.digest {
            return Err(ReleaseReceiptError::MismatchedIntent);
        }
        let expected: BTreeSet<_> = intent.operations.iter().map(|operation| operation.id.clone()).collect();
        let actual: BTreeSet<_> = self.outcomes.keys().cloned().collect();
        if actual != expected {
            return Err(ReleaseReceiptError::MismatchedOperationRoster);
        }
        Ok(())
    }

    fn from_wire(wire: ReleaseReceiptV1Wire) -> Result<Self, ReleaseReceiptError> {
        if wire.schema_version != Self::SCHEMA_VERSION {
            return Err(ReleaseReceiptError::UnsupportedSchema {
                found: wire.schema_version,
            });
        }
        let mut outcomes = BTreeMap::new();
        for entry in wire.outcomes {
            if outcomes.insert(entry.operation.clone(), entry.outcome).is_some() {
                return Err(ReleaseReceiptError::DuplicateOperation {
                    id: Box::new(entry.operation),
                });
            }
        }
        Ok(Self {
            schema_version: wire.schema_version,
            intent_digest: wire.intent_digest,
            outcomes,
        })
    }
}

//! Callisto's single disk-write primitive.
//!
//! This lives in Layer 1 (`callisto-model`) rather than alongside the manifest
//! editors because durable file replacement is not a manifest concern: the
//! changelog writer, the pre-mode state file, and the config scaffolder all
//! need it too. Hosting it here means those callers do not have to take a
//! dependency on `callisto-manifests` purely to reach the filesystem.

use std::io::{self, Write};
use std::path::Path;

use crate::ApplyPermit;
use tempfile::NamedTempFile;

/// Trait for durable changeset and manifest storage operations.
pub trait ChangesetStorage {
    /// Writes content atomically with parent and grandparent directory journal flushing.
    ///
    /// # Errors
    ///
    /// Returns `Err` on any I/O failure: directory creation, temp-file creation, write, sync, or persist.
    fn atomic_write_durable(&self, content: &str, permit: &ApplyPermit) -> io::Result<()>;
}

impl ChangesetStorage for Path {
    fn atomic_write_durable(&self, content: &str, permit: &ApplyPermit) -> io::Result<()> {
        atomic_write(self, content, permit)
    }
}

/// Durably replaces `path`'s contents with `content`.
///
/// The [`ApplyPermit`] is unused at runtime and exists purely as a compile-time
/// obligation: this is callisto's single disk-write primitive, so requiring a
/// permit here means no code path can reach the filesystem without having first
/// consulted the dry-run flag. See [`crate::permit`].
///
/// # Errors
///
/// Returns the first I/O error encountered: creating parent directories, writing the temp file,
/// flushing, fsyncing, or persisting (renaming) to `path`.
pub fn atomic_write(path: &Path, content: &str, permit: &ApplyPermit) -> io::Result<()> {
    let _permit = permit;
    let raw_parent = path.parent().unwrap_or_else(|| Path::new("."));
    let parent = if raw_parent.as_os_str().is_empty() {
        Path::new(".")
    } else {
        raw_parent
    };
    std::fs::create_dir_all(parent)?;

    let mut temp = NamedTempFile::new_in(parent)?;
    temp.write_all(content.as_bytes())?;
    temp.flush()?;
    temp.as_file().sync_all()?;
    temp.persist(path).map_err(|e| e.error)?;

    if let Ok(parent_file) = std::fs::File::open(parent) {
        let _res = parent_file.sync_all();
    }
    if let Some(grandparent) = parent.parent() {
        if !grandparent.as_os_str().is_empty() {
            if let Ok(gp_file) = std::fs::File::open(grandparent) {
                let _res = gp_file.sync_all();
            }
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ApplyPermit;
    use tempfile::tempdir;

    #[test]
    fn atomic_write_creates_file_with_correct_content() {
        let dir = tempdir().unwrap();
        let target = dir.path().join("output.txt");
        let content = "callisto atomic write test payload\n";

        atomic_write(&target, content, &ApplyPermit::force_for_tests()).unwrap();

        assert!(target.exists());
        assert_eq!(std::fs::read_to_string(&target).unwrap(), content);
    }

    #[test]
    fn atomic_write_over_existing_file_replaces_content() {
        let dir = tempdir().unwrap();
        let target = dir.path().join("Cargo.toml");
        let permit = ApplyPermit::force_for_tests();

        atomic_write(&target, "[package]\nname = \"foo\"\nversion = \"1.0.0\"\n", &permit).unwrap();
        assert_eq!(
            std::fs::read_to_string(&target).unwrap(),
            "[package]\nname = \"foo\"\nversion = \"1.0.0\"\n"
        );

        atomic_write(&target, "[package]\nname = \"foo\"\nversion = \"1.0.1\"\n", &permit).unwrap();
        assert_eq!(
            std::fs::read_to_string(&target).unwrap(),
            "[package]\nname = \"foo\"\nversion = \"1.0.1\"\n"
        );
    }

    #[test]
    fn atomic_write_creates_missing_parent_directories() {
        let dir = tempdir().unwrap();
        let target = dir.path().join("deep/nested/dir/file.txt");

        atomic_write(&target, "content\n", &ApplyPermit::force_for_tests()).unwrap();

        assert!(target.exists());
        assert_eq!(std::fs::read_to_string(&target).unwrap(), "content\n");
    }

    /// The temp file is created inside the destination directory and consumed
    /// by `persist`, so a completed write must leave the directory holding
    /// exactly the target file — no `.tmpXXXXXX` siblings.
    #[test]
    fn atomic_write_leaves_no_temp_files_behind() {
        let dir = tempdir().unwrap();
        let target = dir.path().join("nested/report.json");

        atomic_write(&target, "{}\n", &ApplyPermit::force_for_tests()).unwrap();

        let entries: Vec<_> = std::fs::read_dir(target.parent().unwrap())
            .unwrap()
            .map(|e| e.unwrap().file_name())
            .collect();
        assert_eq!(entries, vec![std::ffi::OsString::from("report.json")]);
    }

    /// `ChangesetStorage` is the method-call spelling of the same primitive;
    /// it must land the identical bytes at the identical path.
    #[test]
    fn changeset_storage_trait_writes_through_to_atomic_write() {
        let dir = tempdir().unwrap();
        let target = dir.path().join("CHANGELOG.md");

        target
            .as_path()
            .atomic_write_durable("# pkg\n", &ApplyPermit::force_for_tests())
            .unwrap();

        assert_eq!(std::fs::read_to_string(&target).unwrap(), "# pkg\n");
    }
}

/// Production [`RateLimitPolicy`] that always permits the retry the registry
/// asked for. `PublishOrchestrator` already bounds total wait via its 600s
/// cutoff, so this policy has no additional gating to apply.
pub struct AlwaysRetryPolicy;

impl RateLimitPolicy for AlwaysRetryPolicy {
    fn check_rate_limit(&self, _retry_after: Duration) -> Result<(), RegistryError> {
        Ok(())
    }
}

pub struct PublishOrchestrator<R, P, T> {
    client: R,
    policy: P,
    time: T,
    progress: Option<Box<dyn Fn(String) + Send + Sync>>,
    skip_precheck: bool,
}

impl<R, P, T> PublishOrchestrator<R, P, T>
where
    R: RegistryClient,
    P: RateLimitPolicy,
    T: TimeProvider,
{
    pub fn new(client: R, policy: P, time: T) -> Self {
        Self {
            client,
            policy,
            time,
            progress: None,
            skip_precheck: false,
        }
    }

    /// Attach a progress callback that is invoked before each package publish
    /// attempt. The message includes the package name and version.
    pub fn with_progress<F: Fn(String) + Send + Sync + 'static>(mut self, f: F) -> Self {
        self.progress = Some(Box::new(f));
        self
    }

    /// Skips the `is_published` pre-check before every publish attempt,
    /// relying solely on the registry client's own already-published
    /// classification from the `publish()` call itself. Defaults to `false`
    /// (the pre-check runs) since some registries' `publish()` re-runs local
    /// lifecycle scripts (e.g. npm's `prepublishOnly`/`prepack`) even on an
    /// already-published version, which the pre-check avoids. Opt in when
    /// that cost matters more than the pre-check's extra registry round-trip.
    pub fn with_skip_precheck(mut self, skip: bool) -> Self {
        self.skip_precheck = skip;
        self
    }

    pub fn parse_http_429_ttl(retry_after_header: &str) -> Option<Duration> {
        parse_retry_after(retry_after_header)
    }

    fn emit_progress(&self, name: &str, version: &Version) {
        if let Some(ref cb) = self.progress {
            cb(format!("Publishing {name}@{version}…"));
        }
    }

    /// Attempts to publish every package in `plan` to its ecosystem
    /// registry, recording a per-package outcome (or failure) for each one
    /// rather than aborting the whole batch on the first error — one
    /// package's registry rejection or auth failure must not silently erase
    /// the fact that earlier packages in the same run genuinely published or
    /// were already present.
    pub fn execute(&self, plan: &PublishPlan, permit: &ApplyPermit) -> PublishReport {
        let mut attempts = Vec::new();

        for rust_crate in &plan.rust_crates {
            let pkg_id = PackageId::Prefixed {
                ecosystem: Ecosystem::Cargo,
                name: rust_crate.name.clone(),
            };
            self.emit_progress(&rust_crate.name, &rust_crate.version);
            attempts.push(self.attempt_publish(pkg_id, rust_crate.version.clone(), permit));
        }

        for npm_pkg in &plan.npm_platform_packages {
            let pkg_id = PackageId::Prefixed {
                ecosystem: Ecosystem::Npm,
                name: npm_pkg.name.clone(),
            };
            self.emit_progress(&npm_pkg.name, &npm_pkg.version);
            attempts.push(self.attempt_publish(pkg_id, npm_pkg.version.clone(), permit));
        }

        // Names of npm platform packages that did NOT successfully publish
        // above (Published/AlreadyPublished both count as success). A main
        // package declaring one of these in `depends_on_platforms` must not
        // be published: its `optionalDependencies` would reference a version
        // that was never actually uploaded. Scoped to `Ecosystem::Npm`:
        // `depends_on_platforms` is an npm-only construct, and a bare
        // `.name()` carries no ecosystem information, so an unscoped
        // comparison could mistake a same-named failed Cargo crate for a
        // failed npm platform dependency.
        let failed_platform_names: std::collections::HashSet<String> = attempts
            .iter()
            .filter(|a| a.package.ecosystem() == Some(Ecosystem::Npm) && a.result.is_failure())
            .map(|a| a.package.name().to_string())
            .collect();

        for npm_pkg in &plan.npm_main_packages {
            let pkg_id = PackageId::Prefixed {
                ecosystem: Ecosystem::Npm,
                name: npm_pkg.name.clone(),
            };
            let failed_deps: Vec<&str> = npm_pkg
                .depends_on_platforms
                .iter()
                .map(String::as_str)
                .filter(|dep| failed_platform_names.contains(*dep))
                .collect();
            if !failed_deps.is_empty() {
                attempts.push(PublishAttempt {
                    package: pkg_id,
                    version: npm_pkg.version.clone(),
                    result: PublishAttemptResult::Failed {
                        kind: "dependencyFailed".to_string(),
                        error: format!(
                            "skipped: platform dependenc{} failed to publish: {}",
                            if failed_deps.len() == 1 { "y" } else { "ies" },
                            failed_deps.join(", ")
                        ),
                    },
                });
                continue;
            }
            self.emit_progress(&npm_pkg.name, &npm_pkg.version);
            attempts.push(self.attempt_publish(pkg_id, npm_pkg.version.clone(), permit));
        }

        for pypi_pkg in &plan.pypi_packages {
            let pkg_id = PackageId::Prefixed {
                ecosystem: Ecosystem::Pypi,
                name: pypi_pkg.name.clone(),
            };
            self.emit_progress(&pypi_pkg.name, &pypi_pkg.version);
            attempts.push(self.attempt_publish(pkg_id, pypi_pkg.version.clone(), permit));
        }

        PublishReport {
            schema_version: callisto_model::SCHEMA_VERSION,
            attempts,
            diagnostics: Vec::new(),
        }
    }

    fn attempt_publish(&self, package: PackageId, version: Version, permit: &ApplyPermit) -> PublishAttempt {
        let result = match self.publish_with_retry(&package, &version, permit) {
            Ok(PublishOutcome::Published) => PublishAttemptResult::Published,
            Ok(PublishOutcome::AlreadyPublished) => PublishAttemptResult::AlreadyPublished,
            Err(err) => PublishAttemptResult::Failed {
                kind: err.kind_str().to_string(),
                error: err.to_string(),
            },
        };

        PublishAttempt {
            package,
            version,
            result,
        }
    }

