        S: Serializer,
    {
        ReleaseExecutionStateV1Wire {
            schema_version: self.schema_version,
            intent_digest: self.intent_digest.clone(),
            operations: self
                .operations
                .iter()
                .map(|(operation, state)| OperationStateEntryV1 {
                    operation: operation.clone(),
                    state: *state,
                })
                .collect(),
        }
        .serialize(serializer)
