        }
    }

    let plan_text = crate::commands::read_json_arg(&args.plan)?;

    let plan: PublishPlan =
        serde_json::from_str(&plan_text).map_err(|e| CliError::Other(format!("Failed to parse publish plan: {e}")))?;

