    match global.format {
        OutputFormat::Json => write_json(&mut std::io::stdout(), &report)?,
        OutputFormat::Text => render::render_tag(&report, global.dry_run, &mut std::io::stdout())?,
    }

    Ok(ExitCode::SUCCESS)
}

